let result = {};
try {
  result = JSON.parse($json.stdout || '{}');
} catch (e) {
  result = { status: 'parse_error', error: e.message };
}

const isHealthy = result.status === 'ok' || result.passed === true;
const fehlerAnzahl = result.errors ? result.errors.length : 0;

return [{
  json: {
    isHealthy,
    fehlerAnzahl,
    summary: result.summary || 'Gesundheitsprüfung abgeschlossen',
    timestamp: new Date().toISOString()
  }
}];
